const raw = ($json.stdout ?? '').toString().trim();
if (!raw) return [];
const parsed = JSON.parse(raw);
if (!parsed.found) return [];
return [{ json: parsed }];

const raw = ($json.stdout ?? '').toString();
const parsed = JSON.parse(raw);
const whisper = parsed.whisper ?? {};
const segments = Array.isArray(whisper.segments) ? whisper.segments : [];
const normalized = segments.map((s, idx) => ({
  index: idx + 1,
  start: Number(s.start ?? 0),
  end: Number(s.end ?? 0),
  text: (s.text ?? '').toString().trim(),
})).filter((s) => s.text.length > 0);

const prompt = [
  'You are a subtitle cleanup assistant.',
  'Rewrite each segment text for readability while preserving meaning and timestamps.',
  'Do not merge/split segments. Keep same number of segments and order.',
  'Return strict JSON only in this shape:',
  '{"segments":[{"index":1,"text":"..."}]}',
  '',
  'Segments:',
  JSON.stringify(normalized, null, 2),
].join('\n');

return [{
  json: {
    ...$json,
    whisper,
    segments: normalized,
    ollamaPrompt: prompt,
  },
}];

const original = Array.isArray($json.segments) ? $json.segments : [];
const responseStr = ($json.response ?? '').toString().trim();

let cleanedByIndex = new Map();
try {
  const parsed = JSON.parse(responseStr);
  if (Array.isArray(parsed.segments)) {
    for (const seg of parsed.segments) {
      const idx = Number(seg.index);
      const txt = (seg.text ?? '').toString().trim();
      if (Number.isFinite(idx) && txt) cleanedByIndex.set(idx, txt);
    }
  }
} catch (e) {
}

const merged = original.map((seg) => ({
  ...seg,
  text: cleanedByIndex.get(seg.index) ?? seg.text,
}));

function srtTime(sec) {
  const ms = Math.max(0, Math.round(sec * 1000));
  const h = Math.floor(ms / 3600000);
  const m = Math.floor((ms % 3600000) / 60000);
  const s = Math.floor((ms % 60000) / 1000);
  const milli = ms % 1000;
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')},${String(milli).padStart(3, '0')}`;
}

function vttTime(sec) {
  const ms = Math.max(0, Math.round(sec * 1000));
  const h = Math.floor(ms / 3600000);
  const m = Math.floor((ms % 3600000) / 60000);
  const s = Math.floor((ms % 60000) / 1000);
  const milli = ms % 1000;
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}.${String(milli).padStart(3, '0')}`;
}

const srt = merged.map((seg) => `${seg.index}\n${srtTime(seg.start)} --> ${srtTime(seg.end)}\n${seg.text}\n`).join('\n');
const vttBody = merged.map((seg) => `${vttTime(seg.start)} --> ${vttTime(seg.end)}\n${seg.text}\n`).join('\n');
const vtt = `WEBVTT\n\n${vttBody}`;
const cleanedTxt = merged.map((seg) => seg.text).join('\n');

return [{
  json: {
    ...$json,
    cleanedSegments: merged,
    srtBase64: Buffer.from(srt, 'utf8').toString('base64'),
    vttBase64: Buffer.from(vtt, 'utf8').toString('base64'),
    cleanedTxtBase64: Buffer.from(cleanedTxt, 'utf8').toString('base64'),
    processedAt: new Date().toISOString(),
  },
}];
